const now = new Date();
function madridYMD(d){ return d.toLocaleDateString('en-CA', { timeZone:'Europe/Madrid' }); }
function madridDow(d){
  const wd = new Intl.DateTimeFormat('en-US', { timeZone:'Europe/Madrid', weekday:'short' }).format(d);
  return ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].indexOf(wd);
}
function ymdToDate(s){ return new Date(s + 'T00:00:00Z'); }
function ymdFromDate(d){ return d.toISOString().substring(0,10); }
function addDays(s,n){ const d = ymdToDate(s); d.setUTCDate(d.getUTCDate()+n); return ymdFromDate(d); }
const todayYMD     = madridYMD(now);
const daysSinceMon = madridDow(now);
const weekYMD      = addDays(todayYMD, -daysSinceMon);
const lastWeekYMD  = addDays(weekYMD, -7);
const yesterdayYMD = addDays(todayYMD, -1);
const [yy, mm]     = todayYMD.split('-');
const monthYMD     = `${yy}-${mm}-01`;
const agedYMD      = addDays(todayYMD, -5);
return [{ json: {
  today_ymd: todayYMD, yesterday_ymd: yesterdayYMD,
  week_ymd: weekYMD, last_week_ymd: lastWeekYMD,
  month_ymd: monthYMD, aged_ymd: agedYMD,
  now_iso: now.toISOString()
} }];

let acc = $('Cruzar Sprint').first().json || {};
const body = $input.first().json || {};
const metrics = Array.isArray(body.ticket_metrics) ? body.ticket_metrics : [];
const manualResults = (acc.zd_today_manual && acc.zd_today_manual.results) || [];
const ticketsById = new Map();
// Set de IDs que actúan como agentes: solo los que aparecen como assignee_id
// en algún ticket de hoy. Los submitter_id que difieren del requester suelen
// ser usuarios de sistema (integraciones) — NO sirven como prueba de agente.
const agentIds = new Set();
for (const t of manualResults) {
  if (!t || t.id == null) continue;
  ticketsById.set(String(t.id), t);
  if (t.assignee_id) agentIds.add(String(t.assignee_id));
}
const todayManualIds = new Set(ticketsById.keys());
const todayMetrics = metrics.filter(m => m && m.ticket_id != null && todayManualIds.has(String(m.ticket_id)));
const answered = [];
const pending  = [];
const excluded = [];
let usedBusinessCount = 0, usedCalendarCount = 0;
for (const m of todayMetrics) {
  const t = ticketsById.get(String(m.ticket_id)) || {};
  // Preferir tiempo en horas de negocio (excluye 18-9h, fines de semana, festivos
  // según el schedule configurado en Zendesk). Si business no está (no schedule
  // configurado), fallback al calendar (tiempo real). Así un ticket que entra
  // a las 7 AM no acumula 2h de espera antes de las 9.
  const rt = m && m.reply_time_in_minutes;
  let mins = null;
  if (rt) {
    if (typeof rt.business === 'number') { mins = rt.business; usedBusinessCount++; }
    else if (typeof rt.calendar === 'number') { mins = rt.calendar; usedCalendarCount++; }
  }
  // Reason 1: el creador (submitter) es uno de los agentes (= aparece como
  // assignee_id en algún ticket). Esto atrapa el caso 'agente se crea ticket
  // a sí mismo' sin tocar tickets de integraciones (submitter = usuario sistema).
  const submitterIsAgent = t.submitter_id && agentIds.has(String(t.submitter_id));
  // Reason 2: por si acaso, el requester también es agente.
  const requesterIsAgent = t.requester_id && agentIds.has(String(t.requester_id));
  // Reason 3: canal voice → llamada telefónica grabada por el agente, no espera real del cliente.
  const viaChannel = t.via && t.via.channel ? String(t.via.channel).toLowerCase() : null;
  const isVoice = viaChannel === 'voice';
  const row = {
    ticket_id: m.ticket_id,
    subject: t.subject || '(sin asunto)',
    created_at: t.created_at || null,
    submitter_id: t.submitter_id || null,
    requester_id: t.requester_id || null,
    assignee_id: t.assignee_id || null,
    reply_time_min: typeof mins === 'number' ? mins : null,
    url: `https://soporteyurest.zendesk.com/agent/tickets/${m.ticket_id}`
  };
  if (submitterIsAgent || requesterIsAgent || isVoice) {
    const reason = isVoice ? 'voice_channel'
                 : submitterIsAgent ? 'submitter_is_agent'
                 : 'requester_is_agent';
    excluded.push({ ...row, via_channel: viaChannel, _reason: reason });
    continue;
  }
  // mins es number cuando Zendesk YA registró respuesta (business o calendar).
  // Permitimos 0 (respondido en horario al instante, p.ej. ticket de antes de las 9
  // contestado justo al inicio jornada → 0 min business). Si mins es null = sin respuesta.
  if (typeof mins === 'number') answered.push(row);
  else pending.push(row);
}
answered.sort((a,b) => b.reply_time_min - a.reply_time_min);
const times = answered.map(r => r.reply_time_min);
const sample = times.length;
const avgMin = sample ? Math.round(times.reduce((a,b)=>a+b,0) / sample) : null;
const sorted = times.slice().sort((a,b)=>a-b);
const median = sample ? sorted[Math.floor(sample/2)] : null;
const minV = sample ? sorted[0] : null;
const maxV = sample ? sorted[sorted.length-1] : null;
return [{ json: { ...acc,
  frt_avg_min: avgMin,
  frt_sample: sample,
  frt_answered: sample,
  frt_pending: todayMetrics.length - sample - excluded.length,
  frt_excluded_count: excluded.length,
  frt_min: minV,
  frt_max: maxV,
  frt_median: median,
  frt_breakdown: answered,
  frt_pending_list: pending,
  frt_excluded_list: excluded,
  _frt_agent_ids: [...agentIds],
  _frt_used_business: usedBusinessCount,
  _frt_used_calendar: usedCalendarCount
} }];

// Agregar todos los counters en el JSON final (sin histRes-dependent)
const d = $input.first().json;
function count(o){ return (o && (typeof o.count === 'number' ? o.count : (Array.isArray(o.results) ? o.results.length : 0))) || 0; }
function results(o){ return (o && Array.isArray(o.results)) ? o.results : []; }

const today_ia      = count(d.zd_today_ia);
const today_manual  = count(d.zd_today_manual);
const yesterday_ia  = count(d.zd_yesterday_ia);
const yesterday_man = count(d.zd_yesterday_manual);
const week_ia       = count(d.zd_week_ia);
const week_manual   = count(d.zd_week_manual);
const month_ia      = count(d.zd_month_ia);
const month_manual  = count(d.zd_month_manual);
const open          = count(d.zd_open);
const solved_today  = count(d.zd_solved_today);
const aged          = count(d.zd_aged);
const incidencias   = count(d.zd_incidencias);

// Incidencias buckets desde results (HTTP search devuelve hasta 100)
const incRes = results(d.zd_incidencias);
const incidencias_list = incRes.map(t => ({
  id: t.id,
  subject: t.subject || '(sin asunto)',
  status: t.status,
  priority: t.priority,
  created_at: t.created_at,
  organization_id: t.organization_id,
  age_days: t.created_at ? Math.floor((Date.now() - new Date(t.created_at).getTime()) / 86400000) : null,
  url: `https://soporteyurest.zendesk.com/agent/tickets/${t.id}`
}));
const incidencias_buckets = { lt30:0, b30_60:0, b60_100:0, gt100:0 };
for (const t of incidencias_list) {
  const a = t.age_days || 0;
  if (a < 30) incidencias_buckets.lt30++;
  else if (a < 60) incidencias_buckets.b30_60++;
  else if (a < 100) incidencias_buckets.b60_100++;
  else incidencias_buckets.gt100++;
}

// Aged list (puede traer hasta 100 — la HTTP search no pagina)
const agedRes = results(d.zd_aged);
const aged_tickets_list = agedRes
  .filter(t => t && t.id)
  .sort((a,b) => new Date(a.created_at) - new Date(b.created_at))
  .map(t => ({
    id: t.id,
    subject: t.subject || '(sin asunto)',
    status: t.status,
    priority: t.priority,
    created_at: t.created_at,
    organization_id: t.organization_id,
    age_days: t.created_at ? Math.floor((Date.now() - new Date(t.created_at).getTime()) / 86400000) : null,
    url: `https://soporteyurest.zendesk.com/agent/tickets/${t.id}`
  }));

return [{ json: {
  generated_at: new Date().toISOString(),
  _workflow_version: 'light-v1',
  _light: true,
  // Tickets counters
  tickets_today: today_ia + today_manual,
  tickets_today_ia: today_ia,
  tickets_today_manual: today_manual,
  tickets_yesterday: yesterday_ia + yesterday_man,
  tickets_yesterday_ia: yesterday_ia,
  tickets_yesterday_manual: yesterday_man,
  tickets_week: week_ia + week_manual,
  tickets_week_ia: week_ia,
  tickets_week_manual: week_manual,
  tickets_month: month_ia + month_manual,
  tickets_month_ia: month_ia,
  tickets_month_manual: month_manual,
  tickets_open: open,
  tickets_solved_today: solved_today,
  backlog_today: today_manual - solved_today,
  // Operativos
  tickets_aged_3d: aged,
  tickets_incidencias_dev: incidencias,
  aged_tickets_list,
  incidencias_list,
  incidencias_buckets,
  // FRT
  frt_avg_min: d.frt_avg_min ?? null,
  frt_sample: d.frt_sample ?? 0,
  frt_answered: d.frt_answered ?? 0,
  frt_pending: d.frt_pending ?? 0,
  frt_min: d.frt_min ?? null,
  frt_max: d.frt_max ?? null,
  frt_median: d.frt_median ?? null,
  frt_breakdown: d.frt_breakdown || [],
  frt_pending_list: d.frt_pending_list || [],
  frt_excluded_list: d.frt_excluded_list || [],
  frt_excluded_count: d.frt_excluded_count ?? 0,
  _frt_used_business: d._frt_used_business ?? 0,
  _frt_used_calendar: d._frt_used_calendar ?? 0,
  // Sprint breakdown (Asana): incidencias DEV abiertas cruzadas con project
  // Tickets Zendesk (1209422123678036) via custom field ID Zendesk (1213032964664949).
  incidencias_en_sprint: d.incidencias_en_sprint ?? null,
  incidencias_sin_sprint: d.incidencias_sin_sprint ?? null,
  incidencias_en_sprint_list: d.incidencias_en_sprint_list || [],
  incidencias_sin_sprint_list: d.incidencias_sin_sprint_list || [],
  // Tipo en Asana de las incidencias DEV abiertas con tarea (Error incluye P1).
  incidencias_tipo_error: d.incidencias_tipo_error ?? null,
  incidencias_tipo_externo: d.incidencias_tipo_externo ?? null,
  incidencias_con_tarea: d.incidencias_con_tarea ?? null
} }];

// Cruza incidencias DEV (Zendesk) con Asana project Tickets Zendesk
// via custom field ID Zendesk (1213032964664949). Para cada ticket:
//   en_sprint  = tarea Asana no-completada Y en algun proyecto cuyo
//                nombre matchea /sprint/i
//   resuelta   = tarea ya en Produccion (completada o en una seccion
//                'Produccion'): se considera resuelta aunque el ticket
//                siga abierto o se reabra en Zendesk. Se QUITA de
//                zd_incidencias, asi no cuenta en el total, ni en los
//                tramos de antiguedad, ni en ninguna caja del panel.
//   sin_sprint = resto (sin tarea Asana, o tarea abierta fuera de Sprint)
const ZD_FIELD_GID = '1213032964664949';

const acc = $('Guardar Incidencias').first().json || {};
const incRes = (acc.zd_incidencias && Array.isArray(acc.zd_incidencias.results))
  ? acc.zd_incidencias.results : [];

let tasks = [];
try { tasks = $input.all().map(i => i.json).filter(Boolean); } catch (_) { tasks = []; }

const zdIds = new Set(incRes.map(t => String(t.id)));

// zd_id -> mejor tarea Asana (no-completada prevalece)
const byId = new Map();
for (const t of tasks) {
  const cfs = Array.isArray(t.custom_fields) ? t.custom_fields : [];
  const cf = cfs.find(c => c && c.gid === ZD_FIELD_GID);
  if (!cf) continue;
  let val = (cf.display_value != null ? cf.display_value : cf.text_value);
  if (val == null) continue;
  val = String(val).trim();
  if (!val) continue;
  const matched = zdIds.has(val)
    ? [val]
    : (val.match(/\d{2,7}/g) || []).filter(x => zdIds.has(x));
  for (const id of matched) {
    const ex = byId.get(id);
    if (!ex || (ex.completed && !t.completed)) byId.set(id, t);
  }
}

const isSprintTask = (t) => {
  if (!t || t.completed) return false;
  const ms = Array.isArray(t.memberships) ? t.memberships : [];
  return ms.some(m => m && m.project && typeof m.project.name === 'string'
                    && /sprint/i.test(m.project.name));
};

const enProduccion = (t) => !!t && (t.completed ||
  (Array.isArray(t.memberships) ? t.memberships : [])
    .some(m => m && m.section && /producci[oó]n/i.test(m.section.name || '')));

// Estado = seccion de la tarea en el Sprint mas reciente (una tarea arrastrada
// sigue en los sprints viejos como 'No Finalizada (SSP)').
const sprintNum = (m) => { const x = /#\s*(\d+)/.exec(m.project.name || ''); return x ? Number(x[1]) : -1; };
const sprintEstado = (t) => {
  const ms = (Array.isArray(t.memberships) ? t.memberships : [])
    .filter(m => m && m.project && /sprint/i.test(m.project.name || ''))
    .sort((a, b) => sprintNum(b) - sprintNum(a));
  const m = ms[0];
  return (m && m.section && m.section.name) ? m.section.name : 'Sin estado';
};

let en = 0, sin = 0;
const en_list = [];
const sin_list = [];
const resueltas_list = [];
for (const tk of incRes) {
  const id = String(tk.id);
  const t = byId.get(id);
  const entry = {
    id: tk.id,
    url: `https://soporteyurest.zendesk.com/agent/tickets/${tk.id}`,
    asana_url: (t && t.permalink_url) ? t.permalink_url : null
  };
  // Produccion manda sobre Sprint: una tarea en la columna Produccion de su
  // sprint mas reciente ya esta resuelta (antes contaba como 'en sprint').
  const sprintProd = !!t && isSprintTask(t) && /producci[oó]n/i.test(sprintEstado(t));
  if (t && isSprintTask(t) && !sprintProd) { en++; en_list.push({ ...entry, estado: sprintEstado(t) }); }
  else if (sprintProd || enProduccion(t)) { resueltas_list.push(entry); }
  else { sin++; sin_list.push(entry); }
}

const resueltasIds = new Set(resueltas_list.map(e => String(e.id)));

// Tipo (campo Asana 1204987846680852) de las incidencias abiertas que tienen tarea.
// Error incluye 'ERROR - P1' (decision usuario 13-nov); el resto de tipos no se cuenta.
const TIPO_GID = '1204987846680852';
const tipoDe = (t) => {
  const cf = (Array.isArray(t.custom_fields) ? t.custom_fields : []).find(c => c && c.gid === TIPO_GID);
  return String((cf && cf.display_value) || '').trim().toLowerCase();
};
let tipoError = 0, tipoExterno = 0, conTarea = 0;
for (const tk of incRes) {
  const id = String(tk.id);
  const t = byId.get(id);
  if (!t || resueltasIds.has(id)) continue;
  conTarea++;
  const tipo = tipoDe(t);
  if (tipo === 'error externo') tipoExterno++;
  else if (tipo === 'error' || /^error\s*-\s*p1$/.test(tipo)) tipoError++;
}
const zdInc = acc.zd_incidencias || {};
const zdIncCount = typeof zdInc.count === 'number' ? zdInc.count : incRes.length;

return [{ json: {
  ...acc,
  zd_incidencias: {
    ...zdInc,
    results: incRes.filter(t => !resueltasIds.has(String(t.id))),
    count: Math.max(0, zdIncCount - resueltasIds.size)
  },
  incidencias_resueltas_list: resueltas_list,
  incidencias_en_sprint: en,
  incidencias_sin_sprint: sin,
  incidencias_en_sprint_list: en_list,
  incidencias_sin_sprint_list: sin_list,
  incidencias_tipo_error: tipoError,
  incidencias_tipo_externo: tipoExterno,
  incidencias_con_tarea: conTarea
} }];

// Cache en static data del workflow. TTL 5 min.
// Evita que cada carga del panel dispare 13 busquedas contra Zendesk
// (la cuota de la Search API es por cuenta y la comparten todos los workflows).
const TTL_MS = 5 * 60 * 1000;
const sd = $getWorkflowStaticData('global');
const cached = sd.light_payload || null;
const cachedAt = sd.light_cached_at || null;
const edadMs = cachedAt ? (Date.now() - new Date(cachedAt).getTime()) : null;
const fresca = !!(cached && edadMs !== null && edadMs >= 0 && edadMs < TTL_MS);
return [{ json: {
  _cache_hit: fresca,
  _cached_at: cachedAt,
  _cache_age_s: edadMs === null ? null : Math.round(edadMs / 1000),
  _payload: fresca ? cached : null
} }];

// Devuelve el payload cacheado tal cual, marcando que viene de cache.
const d = $input.first().json;
const p = d._payload || {};
return [{ json: { ...p, _cache_hit: true, _cached_at: d._cached_at, _cache_age_s: d._cache_age_s } }];

// Guarda el resultado recien calculado en static data para los siguientes 5 min.
const payload = $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.light_payload = payload;
sd.light_cached_at = new Date().toISOString();
return [{ json: { ...payload, _cache_hit: false, _cached_at: sd.light_cached_at, _cache_age_s: 0 } }];
